    // ─────────── فصل ۱: خانواده کارامازوف ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "The Karamazov Family", titlePersian = "خانواده کارامازوف",
        paragraphs = listOf(
            StoryParagraph("Fyodor Pavlovich Karamazov was a strange and unpleasant man, the kind of man who seems to take pleasure in making others miserable.", "فیودور پاولویچ کارامازوف مردی عجیب و ناخوشایند بود، از آن نوع مردانی که به نظر می‌رسد از بدبخت کردن دیگران لذت می‌برند."),
            StoryParagraph("He was a landowner of modest means and immodest appetites; he loved money, and women, and drink, and above all, he loved making a fool of himself in public.", "او زمین‌داری با ثروت متوسط و شهوات بی‌شرم بود؛ پول را دوست داشت و زنان را و شراب را و بیش از همه دوست داشت در ملأ عام خودش را لودگی کند."),
            StoryParagraph("He had been married twice, and both of his wives had died young — some said of grief, others said of his cruelty.", "دو بار ازدواج کرده بود و هر دو همسرش جوان مرده بودند — برخی می‌گفتند از اندوه، دیگران از بی‌رحمی او."),
            StoryParagraph("His first wife, Adelaida, had run away from him, and had died in Petersburg under mysterious circumstances.", "همسر اولش، آدلایدا، از او فرار کرده و در پترزبورگ در شرایط مرموزی مرده بود."),
            StoryParagraph("His second wife, Sofia, had been a beautiful and gentle woman, and she had borne him two sons before she too died.", "همسر دومش، سوفیا، زنی زیبا و لطیف بوده و پیش از مرگش دو پسر برایش زاده بود."),
            StoryParagraph("From his first marriage, he had one son, Dmitri, whom he had neglected and forgotten almost from the day of his birth.", "از ازدواج اولش پسری داشت، دمیتری، که از روز تولدش تقریباً نادیده گرفته و فراموش کرده بود."),
            StoryParagraph("From his second marriage, he had two sons, Ivan and Alyosha, whom he had also neglected, though he had not entirely forgotten them.", "از ازدواج دومش دو پسر داشت، ایوان و آلیوشا، که آن‌ها را هم نادیده گرفته بود، هرچند کاملاً فراموششان نکرده بود."),
            StoryParagraph("There was also a fourth son, Smerdyakov, born to a mute woman who lived in Fyodor's house and who was widely believed to be his daughter by a mad woman.", "پسری چهارم هم بود، اسمردیاکوف، زاده زنی لال که در خانه فیودور زندگی می‌کرد و به‌طور گسترده باور می‌شد دخترش از زنی دیوانه است."),
            StoryParagraph("Smerdyakov was Fyodor's servant, and perhaps his son, and certainly his curse — a strange and bitter young man with epilepsy and a talent for cruelty.", "اسمردیاکوف خدمتکار فیودور بود و شاید پسرش و قطعاً نفرینش — جوانی عجیب و تلخ با صرع و استعدادی برای بی‌رحمی."),
            StoryParagraph("The three legitimate sons had grown up apart from each other and from their father.", "سه پسر قانونی جدا از همدیگر و از پدرشان بزرگ شده بودند."),
            StoryParagraph("Dmitri, the eldest, had been raised by a distant relative, and had become a soldier, a gambler, a passionate and impulsive man.", "دمیتری، بزرگ‌ترین، توسط خویشاوندی دور بزرگ شده بود و به سرباز تبدیل شده بود، به قمارباز، به مردی پرشور و تکانشی."),
            StoryParagraph("Ivan, the middle son, had been raised by a benefactor, and had become a scholar, a philosopher, a man of cold intellect and burning questions.", "ایوان، پسر میانی، توسط نیکوکاری بزرگ شده بود و به دانشمند تبدیل شده بود، به فیلسوف، به مردی با عقل سرد و پرسش‌های سوزان."),
            StoryParagraph("Alyosha, the youngest, had been raised in a monastery, and had become a novice, a young man of deep faith and gentle love.", "آلیوشا، کوچک‌ترین، در صومعه‌ای بزرگ شده بود و به مبتدی تبدیل شده بود، به جوانی با ایمان عمیق و عشق لطیف."),
            StoryParagraph("The three brothers had not seen each other for years, and they might never have seen each other again, if not for a certain meeting that was to take place at the monastery.", "سه برادر سال‌ها همدیگر را ندیده بودند و شاید هرگز دوباره نمی‌دیدند، اگر نه برای ملاقاتی مشخص که قرار بود در صومعه رخ دهد."),
            StoryParagraph("The meeting had been arranged by Alyosha, who hoped to reconcile his father with his brother Dmitri, who had come to claim what he believed was his inheritance.", "ملاقات توسط آلیوشا ترتیب داده شده بود، که امیدوار بود پدرش را با برادرش دمیتری آشتی دهد، که آمده بود ادعای آنچه باور داشت ارثش است کند."),
            StoryParagraph("Dmitri believed that his father owed him money — money left to him by his mother, which his father had spent on himself.", "دمیتری باور داشت پدرش به او پول بدهکار است — پولی که مادرش برایش گذاشته بود و پدرش برای خودش خرج کرده بود."),
            StoryParagraph("Fyodor denied the debt, and indeed, he claimed that Dmitri owed him money, and he had no intention of giving him a single kopek.", "فیودور بدهی را انکار می‌کرد و در واقع ادعا می‌کرد دمیتری به او بدهکار است و قصد نداشت یک کوپک هم به او بدهد."),
            StoryParagraph("But the real conflict between father and son was not about money; it was about a woman named Agrafena Alexandrovna Svetlova, whom everyone called Grushenka.", "اما درگیری واقعی میان پدر و پسر درباره پول نبود؛ درباره زنی به نام آگرافنا الکساندرونا سوتلوا بود، که همه گروشنکا صدایش می‌زدند."),
            StoryParagraph("Grushenka was a beautiful woman of twenty-two, who had been betrayed in love and who had become cold, calculating, and dangerous.", "گروشنکا زنی زیبا بیست و دو ساله بود، که در عشق خیانت دیده بود و سرد شده بود، حساب‌گر و خطرناک."),
            StoryParagraph("She was, in some sense, the mistress of both father and son, and both of them were desperate to marry her.", "او به نوعی معشوقه هر دو پدر و پسر بود و هر دو مشتاق ازدواج با او بودند."),
            StoryParagraph("Dmitri was madly, hopelessly, destructively in love with Grushenka; he would have given his life for her.", "دمیتری دیوانه‌وار، ناامیدانه، ویران‌گرانه عاشق گروشنکا بود؛ زندگی‌اش را برایش می‌داد."),
            StoryParagraph("Fyodor, meanwhile, wanted to marry her out of spite — to humiliate his son, to prove his own power, to satisfy his lust.", "فیودور در همین حال می‌خواست به قصد کینه با او ازدواج کند — تحقیر پسرش، اثبات قدرتش، ارضای شهوتش."),
            StoryParagraph("And so the two men, father and son, were rivals for the same woman, and their rivalry would end in blood.", "و اینگونه آن دو مرد، پدر و پسر، برای همان زن رقیب بودند و رقابتشان به خون می‌انجامید."),
            StoryParagraph("Alyosha, who loved both his father and his brother, was caught between them, unable to help, unable to choose, unable to stop what was coming.", "آلیوشا که هم پدرش و هم برادرش را دوست داشت، میانشان گرفتار شده بود، ناتوان از کمک، ناتوان از انتخاب، ناتوان از متوقف کردن آنچه می‌آمد."),
            StoryParagraph("Ivan, who had long since lost any respect for his father, watched the drama with cold detachment, seeing in it only further proof of the meaninglessness of the world.", "ایوان که مدت‌ها پیش هر احترامی برای پدرش را از دست داده بود، درام را با جدایی سرد تماشا می‌کرد و در آن تنها اثبات بیشتری از بی‌معنایی جهان می‌دید."),
            StoryParagraph("Smerdyakov, the bastard servant, watched everything with his strange yellow eyes, and said nothing, and thought much.", "اسمردیاکوف، خدمتکار حرام‌زاده، همه چیز را با چشمان زرد عجیبش تماشا می‌کرد و چیزی نمی‌گفت و زیاد فکر می‌کرد."),
            StoryParagraph("The meeting at the monastery took place on a hot afternoon in late August, in the cell of the revered elder, Father Zosima.", "ملاقات در صومعه در بعدازظهری گرم در اواخر اوت، در حجره مرشد محترم، پدر زوسیما، رخ داد."),
            StoryParagraph("Father Zosima was a starets — a spiritual elder, a man of great wisdom and great love, whom people came from all over Russia to consult.", "پدر زوسیما استارتس بود — مرشد روحانی، مردی با خرد فراوان و عشق فراوان، که مردم از سراسر روسیه برای مشورتش می‌آمدند."),
            StoryParagraph("He was old and sick, and near the end of his life, but his eyes were bright with intelligence and compassion.", "پیر و مریض بود و نزدیک پایان زندگی‌اش، اما چشمانش از هوش و شفقت می‌درخشید."),
            StoryParagraph("He received the Karamazovs in his cell, and he listened to their quarrels, and he said nothing for a long time.", "کارامازوف‌ها را در حجره‌اش پذیرفت و به مشاجره‌شان گوش داد و مدت طولانی چیزی نگفت."),
            StoryParagraph("Then he spoke, and his words would echo through the novel, through the lives of everyone present, through the centuries.", "بعد صحبت کرد و کلماتش در تمام رمان می‌پیچید، در زندگی هر حاضری، در طول قرن‌ها."),
            StoryParagraph("'Do not judge,' he said. 'Do not condemn. Do not hate. Love everyone. Love everything.'", "گفت: «قضاوت نکنید. محکوم نکنید. متنفر نباشید. همه را دوست بدارید. همه چیز را دوست بدارید.»"),
            StoryParagraph("'For love is the only thing that can save us,' he continued. 'Love is the only thing that makes life bearable, that makes suffering meaningful, that makes death a passage rather than an end.'", "ادامه داد: «زیرا عشق تنها چیزی است که می‌تواند نجاتمان دهد. عشق تنها چیزی است که زندگی را تحمل‌پذیر می‌کند، رنج را معنادار، مرگ را گذرگاهی نه پایانی.»"),
            StoryParagraph("'If you love everything, you will perceive the divine mystery in things. And once you have perceived it, you will begin to comprehend it ceaselessly, more and more every day. And you will come at last to love the whole world with an all-embracing love.'", "«اگر همه چیز را دوست بدارید، رمز الهی را در چیزها درک خواهید کرد. و هنگامی که آن را درک کردید، شروع خواهید کرد به فهمیدنش بی‌وقفه، هر روز بیشتر و بیشتر. و سرانجام خواهید رسید به عشق ورزیدن به تمام جهان با عشقی فراگیر.»"),
            StoryParagraph("The old man spoke for a long time, and everyone listened, and no one fully understood, and yet everyone felt that something important had been said.", "پیرمرد مدت طولانی صحبت کرد و همه گوش دادند و هیچ‌کس کاملاً نفهمید و با این حال همه حس کردند چیزی مهم گفته شده."),
            StoryParagraph("When the Karamazovs left the monastery, they were not reconciled; on the contrary, the quarrel between father and son had grown worse.", "وقتی کارامازوف‌ها صومعه را ترک کردند، آشتی نکرده بودند؛ برعکس، دعوای میان پدر و پسر بدتر شده بود."),
            StoryParagraph("But something had changed, in each of them, in ways that none of them would fully understand until much later.", "اما چیزی در هر یک از آنان تغییر کرده بود، به شیوه‌هایی که هیچ‌کدام تا مدت‌ها بعد کاملاً نمی‌فهمیدند."),
            StoryParagraph("And the seeds of tragedy had been planted, and the harvest would be terrible.", "و بذرهای تراژدی کاشته شده بود و برداشت هولناک می‌بود."),
            StoryParagraph("And so began the story of the Karamazov brothers, the story of a family, the story of Russia, the story of the human soul.", "و اینگونه داستان برادران کارامازوف آغاز شد، داستان یک خانواده، داستان روسیه، داستان روح انسانی.")
        )
    )

    // ─────────── فصل ۲: بازپرس بزرگ ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "The Grand Inquisitor", titlePersian = "بازپرس بزرگ",
        paragraphs = listOf(
            StoryParagraph("Ivan Karamazov was a brilliant young man, a graduate of the university, a writer of articles on philosophy and religion, a man who had thought deeply about everything and believed in nothing.", "ایوان کارامازوف جوانی درخشان بود، فارغ‌التحصیل دانشگاه، نویسنده مقالاتی درباره فلسفه و دین، مردی که عمیقاً درباره همه چیز فکر کرده بود و به هیچ چیز باور نداشت."),
            StoryParagraph("He was a rationalist, a skeptic, a materialist — or so he told himself — and he could not accept the world as God had made it.", "او عقل‌گرا بود، شک‌گرا، ماتریالیست — یا اینطور به خودش می‌گفت — و نمی‌توانست جهان را آن‌گونه که خدا ساخته بود بپذیرد."),
            StoryParagraph("He could not accept the suffering of innocent children; he could not accept the cruelty of nature; he could not accept the apparent meaninglessness of existence.", "نمی‌توانست رنج کودکان بی‌گناه را بپذیرد؛ نمی‌توانست بی‌رحمی طبیعت را بپذیرد؛ نمی‌توانست بی‌معنایی ظاهری وجود را بپذیرد."),
            StoryParagraph("And so he had constructed, in his mind, a great argument against God — an argument that he wanted to share with his brother Alyosha.", "و بنابراین در ذهنش استدلالی بزرگ علیه خدا ساخته بود — استدلالی که می‌خواست با برادرش آلیوشا قسمت کند."),
            StoryParagraph("They met in a tavern in the town, one evening in late spring, and they talked about many things: about Russia, about the peasants, about the future of the world.", "یک عصر در اواخر بهار در میخانه‌ای در شهر ملاقات کردند و درباره چیزهای زیادی صحبت کردند: درباره روسیه، درباره دهقانان، درباره آینده جهان."),
            StoryParagraph("But the conversation was only a prelude; Ivan had something else on his mind, something that he had been preparing to say for a long time.", "اما گفتگو تنها پیش‌درآمدی بود؛ ایوان چیز دیگری در ذهن داشت، چیزی که مدت‌ها آماده گفته‌اش بود."),
            StoryParagraph("'I want to tell you a story,' Ivan said. 'A poem, actually. I wrote it in my head, but I have never written it down. I want to tell it to you.'", "ایوان گفت: «می‌خواهم داستانی برایت بگویم. در واقع، شعری. در ذهنم نوشتمش اما هرگز روی کاغذ نیاوردمش. می‌خواهم برایت بگویمش.»"),
            StoryParagraph("'Tell me,' Alyosha said, and he leaned forward, and he listened.", "آلیوشا گفت: «بگو.» و به جلو خم شد و گوش داد."),
            StoryParagraph("'My poem,' Ivan said, 'is set in Spain, in Seville, at the height of the Inquisition, when heretics were burned daily, when the Grand Inquisitor ruled the land with terror.'", "ایوان گفت: «شعر من در اسپانیا می‌گذرد، در سویل، در اوج تفتیش عقاید، زمانی که بدعت‌گذاران هر روز سوزانده می‌شدند، زمانی که بازپرس بزرگ با ترور بر سرزمین حکومت می‌کرد.»"),
            StoryParagraph("'And one day, in the midst of all this horror, Jesus Christ returns to Earth, in the form of a man, in the streets of Seville.'", "«و یک روز، در میانه تمام این وحشت، عیسی مسیح به زمین بازمی‌گردد، به شکل یک انسان، در خیابان‌های سویل.»"),
            StoryParagraph("'He walks among the people, and they recognize him, one by one, and they are filled with joy, and they come to him, and he heals them, and they weep with happiness.'", "«او میان مردم راه می‌رود و آنان یکی‌یکی می‌شناسندش و پر از شادی می‌شوند و به نزدش می‌آیند و او شفایشان می‌دهد و آنان از شادی می‌گریند.»"),
            StoryParagraph("'He heals a blind man, and he raises a dead child, and the whole city is in an uproar, and everyone wants to see him, to touch him, to hear him speak.'", "«مردی کور را شفا می‌دهد و کودکی مرده را زنده می‌کند و تمام شهر به هم می‌ریزد و همه می‌خواهند ببینندش، لمسش کنند، حرفش را بشنوند.»"),
            StoryParagraph("'And then the Grand Inquisitor himself walks by, an old man of ninety, in his coarse monk's robe, and he sees what is happening, and he orders the guards to arrest Jesus.'", "«و بعد خود بازپرس بزرگ از آنجا می‌گذرد، پیرمردی نود ساله، در جامه درشت راهبان و می‌بیند چه اتفاقی می‌افتد و به نگهبانان دستور می‌دهد عیسی را دستگیر کنند.»"),
            StoryParagraph("'The guards take him, and they lead him to a cell in the prison, and they lock the door, and there he sits, alone, in the darkness.'", "«نگهبانان او را می‌برند و به حجره‌ای در زندان می‌برند و در را قفل می‌کنند و او آنجا می‌نشیند، تنها، در تاریکی.»"),
            StoryParagraph("'At midnight, the Grand Inquisitor himself enters the cell, alone, with a lamp in his hand, and he stands before his prisoner, and he looks at him, and he says nothing.'", "«در نیمه‌شب، خود بازپرس بزرگ وارد حجره می‌شود، تنها، با چراغی در دستش و پیش زندانی‌اش می‌ایستد و نگاهش می‌کند و چیزی نمی‌گوید.»"),
            StoryParagraph("'Then the old man begins to speak, and his words are the heart of the poem, the heart of Ivan's argument, the heart of everything.'", "«بعد پیرمرد شروع به صحبت می‌کند و کلماتش قلب شعر است، قلب استدلال ایوان، قلب همه چیز.»"),
            StoryParagraph("'You came to us again, the Inquisitor says. You promised us freedom, and you gave us freedom, and we have spent fifteen centuries trying to undo that gift.'", "«بازپرس می‌گوید: دوباره به نزد ما آمدی. به ما آزادی وعده دادی و آزادی دادی و ما پانزده قرن صرف کرده‌ایم تا آن هدیه را باطل کنیم.»"),
            StoryParagraph("'You gave humans freedom, but humans do not want freedom. They want security. They want bread. They want someone to tell them what to do.'", "«تو به انسان‌ها آزادی دادی اما انسان‌ها آزادی نمی‌خواهند. امنیت می‌خواهند. نان می‌خواهند. کسی که به آنان بگوید چه کنند.»"),
            StoryParagraph("'And so the Church has taken that freedom back, the Inquisitor says. The Church has given them bread, and mystery, and authority. And they are happy.'", "«و بنابراین کلیسا آن آزادی را پس گرفته، بازپرس می‌گوید. کلیسا به آنان نان داده و رمز و اقتدار. و آنان خوشحالند.»"),
            StoryParagraph("'We have corrected your work, the Inquisitor says. We have taken away the freedom that was too heavy for them to bear. And they love us for it.'", "«ما کارت را تصحیح کرده‌ایم، بازپرس می‌گوید. آزادی‌ای را که برای تحملش بیش از حد سنگین بود از آنان گرفته‌ایم. و آنان برای آن دوستمان دارند.»"),
            StoryParagraph("'You could have given them bread, and they would have followed you. You could have given them miracles, and they would have believed in you. You could have given them authority, and they would have obeyed you.'", "«می‌توانستی به آنان نان بدهی و دنبالت می‌آمدند. می‌توانستی به آنان معجزه بدهی و به تو ایمان می‌آوردند. می‌توانستی به آنان اقتدار بدهی و اطاعتت می‌کردند.»"),
            StoryParagraph("'But you gave them freedom, and they have suffered ever since, and they will always suffer, because freedom is a burden that human beings cannot bear.'", "«اما آزادی به آنان دادی و از آن زمان رنج کشیده‌اند و همیشه رنج می‌کشند، زیرا آزادی باری است که انسان‌ها نمی‌توانند تحملش کنند.»"),
            StoryParagraph("'Tomorrow, the Inquisitor says, I will burn you at the stake, as I have burned hundreds of heretics. And the people, the same people you healed, will watch, and they will not protest.'", "«فردا، بازپرس می‌گوید، تو را بر تیر آتش می‌سوزانم، همانطور که صدها بدعت‌گذار را سوزانده‌ام. و مردم، همان مردمی که شفایشان دادی، تماشا می‌کنند و اعتراض نمی‌کنند.»"),
            StoryParagraph("'And so ends my poem,' Ivan said. 'And so ends my argument. If God is good, why does he allow such suffering? If God is powerful, why does he permit such cruelty?'", "ایوان گفت: «و اینگونه شعر من پایان می‌یابد. و اینگونه استدلال من. اگر خدا خوب است، چرا اجازه می‌دهد چنین رنجی باشد؟ اگر خدا تواناست، چرا اجازه می‌دهد چنین بی‌رحمی باشد؟»"),
            StoryParagraph("'And if the answer is that God's ways are mysterious, that we cannot understand his purposes, then I do not want such an answer.'", "«و اگر پاسخ این است که راه‌های خدا مرموز است، که نمی‌توانیم مقاصدش را بفهمیم، پس چنین پاسخی نمی‌خواهم.»"),
            StoryParagraph("'I do not accept this world. I do not accept God's world. I do not accept the suffering of a single child, not for the sake of any future harmony.'", "«من این جهان را نمی‌پذیرم. جهان خدا را نمی‌پذیرم. رنج یک کودک را نمی‌پذیرم، نه به خاطر هیچ هماهنگی آینده.»"),
            StoryParagraph("'I return my ticket to God, Ivan said, with a kind of terrible calm. I do not want a place in a world where such things happen.'", "ایوان با نوعی آرامش هولناک گفت: «بلیطم را به خدا برمی‌گردانم. جایی در جهانی که چنین چیزهایی رخ می‌دهد نمی‌خواهم.»"),
            StoryParagraph("Alyosha listened in silence, and he was shaken, and he did not know what to say.", "آلیوشا در سکوت گوش داد و تکان خورد و نمی‌دانست چه بگوید."),
            StoryParagraph("He had no answer to Ivan's arguments; he had no argument that could match his brother's logic.", "پاسخی برای استدلال‌های ایوان نداشت؛ استدلالی نداشت که همتای منطق برادرش باشد."),
            StoryParagraph("And so, instead of arguing, he did what Alyosha always did: he loved.", "و بنابراین، به جای بحث، کاری کرد که آلیوشا همیشه می‌کرد: عشق ورزید."),
            StoryParagraph("He leaned forward, and he took Ivan's hand, and he said nothing, and tears ran down his cheeks.", "به جلو خم شد و دست ایوان را گرفت و چیزی نگفت و اشک بر گونه‌هایش جاری شد."),
            StoryParagraph("And Ivan, who had not expected this, who had not expected love in the face of his argument, was moved, and did not know what to do.", "و ایوان که این را انتظار نداشت، که در برابر استدلالش انتظار عشق نداشت، متأثر شد و نمی‌دانست چه کند."),
            StoryParagraph("They sat together in the tavern, the two brothers, the two halves of one soul, and they did not speak, because there was nothing to say.", "آن‌ها در میخانه با هم نشستند، دو برادر، دو نیمه از یک روح و صحبت نکردند، چون چیزی برای گفتن نبود."),
            StoryParagraph("The argument was over; the poem was finished; but the questions remained, as they always remain, unanswered and unanswerable.", "استدلال تمام شد؛ شعر تمام شد؛ اما پرسش‌ها باقی ماندند، همانطور که همیشه می‌مانند، بی‌پاسخ و پاسخ‌ناپذیر."),
            StoryParagraph("And that, perhaps, was the point: not to answer, but to ask; not to solve, but to endure; not to understand, but to love.", "و این، شاید، همان نکته بود: نه پاسخ دادن، بلکه پرسیدن؛ نه حل کردن، بلکه تحمل کردن؛ نه فهمیدن، بلکه عشق ورزیدن."),
            StoryParagraph("Ivan could not accept the world, and so he lived in rebellion, and rebellion destroyed him.", "ایوان نمی‌توانست جهان را بپذیرد و بنابراین در شورش زندگی کرد و شورش نابودش کرد."),
            StoryParagraph("Alyosha could not explain the world, and so he lived in love, and love saved him.", "آلیوشا نمی‌توانست جهان را توضیح دهد و بنابراین در عشق زندگی کرد و عشق نجاتش داد."),
            StoryParagraph("And between these two responses, Dostoevsky suggests, lies the whole drama of human existence.", "و میان این دو پاسخ، داستایفسکی پیشنهاد می‌دهد، تمام درام وجود انسانی نهفته است.")
        )
    )

    // ─────────── فصل ۳: قتل ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "The Murder", titlePersian = "قتل",
        paragraphs = listOf(
            StoryParagraph("On a dark and stormy night in late August, Fyodor Pavlovich Karamazov was murdered in his own house.", "در شبی تاریک و طوفانی در اواخر اوت، فیودور پاولویچ کارامازوف در خانه خودش به قتل رسید."),
            StoryParagraph("His body was found by his servant Grigory, who had been struck down by the fleeing murderer and had lain unconscious in the garden for hours.", "جسدش توسط خدمتکارش گریگوری پیدا شد، که توسط قاتل فراری ضربه خورده بود و ساعت‌ها در باغ بی‌هوش افتاده بود."),
            StoryParagraph("An envelope containing three thousand rubles was missing from beneath the old man's pillow.", "پاکتی حاوی سه هزار روبل از زیر بالش پیرمرد گم شده بود."),
            StoryParagraph("Suspicion fell immediately on Dmitri, who had been seen in the vicinity of the house that night, who had been covered in blood when he was arrested, who had spent the missing money lavishly the following morning.", "سوءظن فوراً بر دمیتری افتاد، که آن شب در نزدیکی خانه دیده شده بود، که هنگام دستگیری خون‌آلود بود، که صبح روز بعد پول گمشده را با دست‌ودل‌باز خرج کرده بود."),
            StoryParagraph("Dmitri was arrested and imprisoned, and he was charged with the murder of his father.", "دمیتری دستگیر و زندانی شد و به قتل پدرش متهم شد."),
            StoryParagraph("But Dmitri insisted that he had not killed his father; he insisted that he had gone to the house that night only to see whether Grushenka was there.", "اما دمیتری اصرار کرد پدرش را نکشته؛ اصرار کرد آن شب تنها به خانه رفته بود که ببیند گروشنکا آنجاست یا نه."),
            StoryParagraph("He admitted that he had taken the money, but he said that he had found it, not stolen it; he admitted that he had struck Grigory, but he said it had been in self-defense.", "پذیرفت پول را برداشته اما گفت پیدایش کرده، ندزدیده؛ پذیرفت گریگوری را زده اما گفت دفاع از خودش بوده."),
            StoryParagraph("He was telling the truth, but no one believed him, because the evidence against him was overwhelming, and because everyone wanted to believe that he was guilty.", "راست می‌گفت اما هیچ‌کس باورش نکرد، زیرا شواهد علیه‌اش قاطع بود و چون همه می‌خواستند باور کنند گناهکار است."),
            StoryParagraph("The real murderer was Smerdyakov, the bastard son, the servant with the yellow eyes, the man whom everyone had overlooked.", "قاتل واقعی اسمردیاکوف بود، پسر حرام‌زاده، خدمتکار با چشمان زرد، مردی که همه نادیده گرفته بودند."),
            StoryParagraph("Smerdyakov had been planning the murder for months; he had been waiting for the right night, when the house was empty and his father was alone.", "اسمردیاکوف ماه‌ها برای قتل نقشه کشیده بود؛ منتظر شب مناسب بود، وقتی خانه خالی و پدرش تنها بود."),
            StoryParagraph("He had prepared a signal with Dmitri, without Dmitri's knowledge; he had timed the murder with Dmitri's arrival; he had taken the money and blamed Dmitri for it.", "با دمیتری نشانه‌ای ترتیب داده بود، بدون اطلاع دمیتری؛ قتل را با رسیدن دمیتری زمان‌بندی کرده بود؛ پول را برداشته و دمیتری را متهمش کرده بود."),
            StoryParagraph("Why had he done it? That was the question that no one could answer, the question that tormented everyone who knew him.", "چرا کرده بود؟ این پرسشی بود که هیچ‌کس نمی‌توانست پاسخ دهد، پرسشی که هر کسی که می‌شناختش را عذاب می‌داد."),
            StoryParagraph("Some said it was for the money; others said it was for revenge; still others said it was simply because he could, because he wanted to see what it would feel like to kill.", "بعضی گفتند برای پول بود؛ دیگران گفتند برای انتقام؛ باز هم دیگران گفتند تنها چون می‌توانست، چون می‌خواست ببیند کشتن چه حسی دارد."),
            StoryParagraph("But the truest answer was the one Ivan came to see, the one that would destroy him, the one that would haunt him for the rest of his life.", "اما واقعی‌ترین پاسخ همان بود که ایوان شروع کرد به دیدن، همان که نابودش می‌کرد، همان که باقی عمرش تسخیرش می‌کرد."),
            StoryParagraph("Smerdyakov had killed Fyodor because Ivan had told him that everything was permitted, that there was no God, that there was no morality.", "اسمردیاکوف فیودور را کشته بود چون ایوان به او گفته بود همه چیز مجاز است، خدایی نیست، اخلاقی نیست."),
            StoryParagraph("'You told me that,' Smerdyakov said to Ivan, when they met for the last time. 'You told me that there is no God, and no soul, and no life after death.'", "اسمردیاکوف در آخرین ملاقاتشان به ایوان گفت: «تو به من گفتی. تو به من گفتی خدایی نیست و روحی نیست و زندگی پس از مرگی نیست.»"),
            StoryParagraph("'If there is no God, then everything is permitted,' Smerdyakov continued. 'That was your teaching. And so I killed him. And so I am not guilty. Because guilt requires God.'", "اسمردیاکوف ادامه داد: «اگر خدایی نیست، پس همه چیز مجاز است. این تعلیم تو بود. و بنابراین کشتمش. و بنابراین گناهکار نیستم. زیرا گناه خدا می‌خواهد.»"),
            StoryParagraph("Ivan was destroyed by these words; he realized that his ideas had led to murder, that his philosophy had killed his father.", "ایوان توسط این کلمات نابود شد؛ فهمید ایده‌هایش به قتل انجامیده، فلسفه‌اش پدرش را کشته بود."),
            StoryParagraph("He had wanted to be free from God, free from morality, free from the burden of conscience; and his freedom had produced a monster.", "می‌خواست از خدا آزاد باشد، از اخلاق، از بار وجدان؛ و آزادی‌اش هیولایی تولید کرده بود."),
            StoryParagraph("'I am the murderer,' Ivan said, to himself, to the world, to God. 'I am the real murderer.'", "ایوان به خودش، به جهان، به خدا گفت: «من قاتلم. من قاتل واقعی‌ام.»"),
            StoryParagraph("Smerdyakov, seeing what he had done, seeing that he had destroyed the man he admired most, hanged himself in his room.", "اسمردیاکوف که دید چه کرده، دید مردی که بیش از همه تحسینش می‌کرد را نابود کرده، در اتاقش خودش را حلق‌آویز کرد."),
            StoryParagraph("He left a note, but the note said nothing that anyone could understand; it only said, 'I am killing myself of my own free will.'", "یادداشتی گذاشت اما یادداشت چیزی نمی‌گفت که کسی بفهمد؛ تنها می‌گفت: «با اراده آزاد خودم خودم را می‌کشم.»"),
            StoryParagraph("And so the murderer killed himself, and the innocent man was imprisoned, and the philosopher went mad, and the young monk was left alone with his grief.", "و اینگونه قاتل خودش را کشت و بی‌گناه زندانی شد و فیلسوف دیوانه شد و راهب جوان با اندوهش تنها ماند."),
            StoryParagraph("The night of the murder had been terrible, but the days that followed were worse.", "شب قتل هولناک بود اما روزهایی که در پی آمدند بدتر بودند."),
            StoryParagraph("The town was in shock; the family was destroyed; the foundations of everything everyone had believed had been shaken.", "شهر شوکه شد؛ خانواده نابود شد؛ پایه‌های هر چیزی که همه باور داشتند متزلزل شد."),
            StoryParagraph("And in the midst of all this ruin, Alyosha walked among the survivors, offering what comfort he could, loving everyone, judging no one.", "و در میان تمام این ویرانی، آلیوشا میان بازماندگان قدم زد و تسلی‌ای که می‌توانست عرضه کرد و همه را دوست داشت و هیچ‌کس را قضاوت نکرد."),
            StoryParagraph("He visited his brother Dmitri in prison, and he listened to his rages, his despair, his plans for escape.", "برادرش دمیتری را در زندان ملاقات کرد و به خشم‌هایش گوش داد، به ناامیدی‌اش، به نقشه‌های فرارش."),
            StoryParagraph("'I want to suffer,' Dmitri said, one day, in the midst of his torment. 'I want to be punished. I want to be purified by suffering.'", "دمیتری یک روز در میانه عذابش گفت: «می‌خواهم رنج بکشم. می‌خواهم مجازات شوم. می‌خواهم با رنج پاک شوم.»"),
            StoryParagraph("'Even though you are innocent?' Alyosha asked.", "آلیوشا پرسید: «حتی اگر بی‌گناه باشی؟»"),
            StoryParagraph("'Even though I am innocent,' Dmitri said. 'Because I am guilty in my heart. Because I wanted to kill him. Because I am a Karamazov, and Karamazovs are dirt and filth, and we must be cleansed by fire.'", "دمیتری گفت: «حتی اگر بی‌گناه باشم. زیرا در قلبم گناهکارم. زیرا می‌خواستم بکشمش. زیرا من کارامازوفم و کارامازوف‌ها خاک و کثافتند و باید با آتش پاک شوند.»"),
            StoryParagraph("And so Dmitri chose to accept his punishment, not because he had committed the crime, but because he had desired it.", "و اینگونه دمیتری انتخاب کرد مجازاتش را بپذیرد، نه چون جنایت را مرتکب شده بود، بلکه چون آرزویش را کرده بود."),
            StoryParagraph("This, Dostoevsky suggests, is the deepest truth about guilt: it is not merely a matter of actions, but of desires; not merely of what we do, but of what we want to do.", "این، داستایفسکی پیشنهاد می‌دهد، عمیق‌ترین حقیقت درباره گناه است: تنها مسئله اعمال نیست، بلکه امیال؛ تنها آنچه می‌کنیم نیست، بلکه آنچه می‌خواهیم بکنیم."),
            StoryParagraph("We are all, in some sense, murderers; we are all, in some sense, guilty; and we must all, in some sense, be purified.", "همه‌مان به نوعی قاتلیم؛ همه‌مان به نوعی گناهکاریم؛ و همه‌مان به نوعی باید پاک شویم."),
            StoryParagraph("And that purification, that redemption, comes not through suffering alone, but through suffering accepted, through suffering understood, through suffering transfigured by love.", "و آن پاک شدن، آن رستگاری، نه تنها از طریق رنج می‌آید، بلکه از طریق رنج پذیرفته‌شده، از طریق رنج فهمیده‌شده، از طریق رنجی که عشق دگرگونش کرده."),
            StoryParagraph("And so the murder of Fyodor Karamazov became the beginning of the redemption of his sons.", "و اینگونه قتل فیودور کارامازوف آغازی شد برای رستگاری پسرانش."),
            StoryParagraph("Not immediately, not easily, not without more suffering to come; but the seeds of redemption had been planted, and they would grow.", "نه بلافاصله، نه به‌آسانی، نه بدون رنج بیشتر در راه؛ اما بذرهای رستگاری کاشته شده بود و رشد می‌کردند."),
            StoryParagraph("And that, perhaps, is the meaning of the Karamazov story: that even in the midst of the darkest evil, the light of love can shine.", "و این، شاید، معنای داستان کارامازوف است: که حتی در میان تاریک‌ترین شر، نور عشق می‌تواند بدرخشد.")
        )
    )

    // ─────────── فصل ۴: محاکمه ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "The Trial", titlePersian = "محاکمه",
        paragraphs = listOf(
            StoryParagraph("The trial of Dmitri Karamazov was the greatest event in the town's history.", "محاکمه دمیتری کارامازوف بزرگ‌ترین رویداد تاریخ شهر بود."),
            StoryParagraph("People came from all over the province to watch; every seat in the courtroom was taken; every inch of standing room was filled.", "مردم از تمام استان برای تماشا آمدند؛ هر صندلی در دادگاه اشغال بود؛ هر اینچ جای ایستادن پر بود."),
            StoryParagraph("The prosecutor was a young man named Ippolit Kirillovich, ambitious and clever, determined to make his name with this case.", "دادستان مردی جوان به نام ایپولیت کیریلیویچ بود، جاه‌طلب و باهوش، مصمم به نامی برای خودش در این پرونده ساختن."),
            StoryParagraph("The defense attorney was a famous lawyer from Petersburg, a man named Fetyukovich, brilliant and cynical, feared by every prosecutor in Russia.", "وکیل مدافع وکیلی مشهور از پترزبورگ بود، مردی به نام فتیوکوویچ، درخشان و بدبین، ترس هر دادستانی در روسیه."),
            StoryParagraph("The courtroom was divided: some believed Dmitri was guilty, others believed him innocent, and no one could prove anything.", "دادگاه تقسیم شده بود: برخی باور داشتند دمیتری گناهکار است، دیگران بی‌گناه و هیچ‌کس نمی‌توانست چیزی ثابت کند."),
            StoryParagraph("The prosecutor presented the evidence: the blood on Dmitri's hands, the money in his pocket, the witnesses who had seen him near the house.", "دادستان شواهد را ارائه کرد: خون روی دست‌های دمیتری، پول در جیبش، شاهدان که دیده بودندش نزدیک خانه."),
            StoryParagraph("'The defendant is a man of violence,' the prosecutor said. 'He is a man of passion and cruelty. He killed his father for money, and he would kill again.'", "دادستان گفت: «متهم مردی خشن است. مردی پرشور و بی‌رحم. پدرش را برای پول کشت و دوباره می‌کشد.»"),
            StoryParagraph("'He grew up without a father's love,' the prosecutor continued, 'and so he became a monster. He is a Karamazov, and the Karamazovs are a family of monsters.'", "دادستان ادامه داد: «بدون عشق پدری بزرگ شد و بنابراین به هیولا تبدیل شد. او کارامازوف است و کارامازوف‌ها خانواده‌ای از هیولاها هستند.»"),
            StoryParagraph("The defense attorney responded with an attack on the prosecutor, an attack on the evidence, an attack on the very idea of certainty.", "وکیل مدافع با حمله‌ای به دادستان پاسخ داد، حمله‌ای به شواهد، حمله‌ای به خود ایده یقین."),
            StoryParagraph("'My client is a passionate man,' Fetyukovich said. 'He is a wild man. He is a foolish man. But is he a murderer? That is the question.'", "فتیوکوویچ گفت: «موکل من مردی پرشور است. مردی وحشی است. مردی احمق است. اما آیا قاتل است؟ این پرسش است.»"),
            StoryParagraph("'The evidence is circumstantial,' the defense continued. 'The blood could be from Grigory. The money could have been found. The witnesses could be mistaken.'", "دفاع ادامه داد: «شواهد ظنی است. خون می‌تواند از گریگوری باشد. پول می‌تواند پیدا شده باشد. شاهدان می‌توانند اشتباه کنند.»"),
            StoryParagraph("'And who,' the defense asked, 'is the real murderer? Who had the motive, the opportunity, the coldness, the calculation, that my client clearly lacks?'", "دفاع پرسید: «و قاتل واقعی کیست؟ چه کسی انگیزه داشت، فرصت، خونسردی، محاسبه‌ای که موکل من واضحاً ندارد؟»"),
            StoryParagraph("The defense did not name Smerdyakov; he had died before the trial; but everyone in the courtroom knew whom he meant.", "دفاع اسمردیاکوف را نام نبرد؛ قبل از محاکمه مرده بود؛ اما همه در دادگاه می‌دانستند منظور کیست."),
            StoryParagraph("Ivan was called to testify, and he came to the stand with a strange look in his eyes, a look that the spectators would remember for years.", "ایوان برای شهادت فراخوانده شد و با نگاهی عجیب در چشمانش به جایگاه آمد، نگاهی که تماشاگران سال‌ها به یاد می‌آوردند."),
            StoryParagraph("'I killed him,' Ivan said, to the surprise of everyone. 'I killed my father. Not with my hands, but with my words. Smerdyakov was my instrument.'", "ایوان به حیرت همه گفت: «من کشتمش. پدرم را کشتم. نه با دست‌هایم، بلکه با کلماتم. اسمردیاکوف ابزارم بود.»"),
            StoryParagraph("The courtroom erupted; the judge called for order; the defense asked for a recess; but Ivan would not be silenced.", "دادگاه به هم ریخت؛ قاضی نظم خواست؛ دفاع تقاضای تنفس کرد؛ اما ایوان ساکت نمی‌شد."),
            StoryParagraph("'I told him that everything was permitted,' Ivan said. 'I told him there was no God, no morality, no guilt. And so he killed, and so I killed, and so we are all murderers.'", "ایوان گفت: «به او گفتم همه چیز مجاز است. به او گفتم خدایی نیست، اخلاقی نیست، گناهی نیست. و بنابراین او کشت و بنابراین من کشتم و بنابراین همه‌مان قاتلیم.»"),
            StoryParagraph("But no one believed him; they thought he was mad; they thought he was trying to protect his brother.", "اما هیچ‌کس باورش نکرد؛ فکر کردند دیوانه است؛ فکر کردند تلاش می‌کند برادرش را محافظت کند."),
            StoryParagraph("Ivan had been going mad for weeks; the strain of the trial, the guilt, the fever, had finally broken him.", "ایوان هفته‌ها بود که داشت دیوانه می‌شد؛ فشار محاکمه، گناه، تب، سرانجام شکسته بودش."),
            StoryParagraph("He was led from the courtroom, raving, and he would spend the rest of his life in and out of sanity.", "او را از دادگاه بیرون بردند، در حال هذیان و باقی عمرش را در و خارج از سلامت عقل می‌گذراند."),
            StoryParagraph("Katerina Ivanovna was called to testify, and she told the story of Dmitri's confession, the confession he had made to her years ago, the confession of a man who had wanted to kill his father.", "کاترینا ایوانوونا برای شهادت فراخوانده شد و داستان اعتراف دمیتری را گفت، اعترافی که سال‌ها پیش به او کرده بود، اعتراف مردی که می‌خواست پدرش را بکشد."),
            StoryParagraph("But Katerina loved Dmitri, and she hated him, and she could not decide which feeling was stronger.", "اما کاترینا دمیتری را دوست داشت و از او متنفر بود و نمی‌توانست تصمیم بگیرد کدام احساس قوی‌تر است."),
            StoryParagraph("She testified against him, and then she testified for him, and then she broke down completely and had to be carried from the room.", "علیه‌اش شهادت داد و بعد به نفعش شهادت داد و بعد کاملاً فرو ریخت و مجبور شدند از اتاق ببرندش."),
            StoryParagraph("Grushenka was called, and she told the truth as she saw it, and her truth was the truth of love.", "گروشنکا فراخوانده شد و حقیقت را آن‌گونه که می‌دید گفت و حقیقتش حقیقت عشق بود."),
            StoryParagraph("'Dmitri is not a murderer,' she said, and her voice was clear and strong. 'He is a foolish man, and a passionate man, and a wild man. But he is not a murderer.'", "گفت: «دمیتری قاتل نیست.» و صدایش واضح و قوی بود. «مردی احمق است و پرشور و وحشی. اما قاتل نیست.»"),
            StoryParagraph("'I love him,' she continued. 'I have loved him since the moment I met him. And I know, in my heart, that he is innocent.'", "ادامه داد: «دوستش دارم. از لحظه‌ای که ملاقاتش کردم دوستش داشته‌ام. و در قلبم می‌دانم بی‌گناه است.»"),
            StoryParagraph("But the jury had already made up their minds; they had been swayed by the prosecutor, by the evidence, by their own desire to see someone punished.", "اما هیئت منصفه از قبل تصمیم گرفته بود؛ توسط دادستان متأثر شده بودند، توسط شواهد، توسط میل خودشان به دیدن مجازات کسی."),
            StoryParagraph("After a long deliberation, they returned with their verdict: guilty.", "پس از مشاوره‌ای طولانی، با حکمشان بازگشتند: گناهکار."),
            StoryParagraph("Dmitri was sentenced to twenty years of hard labor in Siberia.", "دمیتری به بیست سال کار سخت در سیبری محکوم شد."),
            StoryParagraph("He heard the verdict without flinching, without protest, without surprise.", "حکم را بدون لرزش شنید، بدون اعتراض، بدون حیرت."),
            StoryParagraph("'I accept,' he said, quietly. 'I accept the punishment. I have deserved it.'", "آرام گفت: «می‌پذیرم. مجازات را می‌پذیرم. سزاوارش بوده‌ام.»"),
            StoryParagraph("Alyosha, who had been in the courtroom throughout, went to his brother and embraced him.", "آلیوشا که تمام محاکمه را در دادگاه بوده بود، به نزد برادرش رفت و در آغوشش گرفت."),
            StoryParagraph("'You are innocent,' Alyosha said. 'You did not kill him.'", "آلیوشا گفت: «بی‌گناهی. نکشتی‌اش.»"),
            StoryParagraph("'I am guilty,' Dmitri said. 'Not of the murder, perhaps. But of everything else. Of the life I have lived, of the man I have been.'", "دمیتری گفت: «گناهکارم. شاید نه به قتل. اما به هر چیز دیگری. به زندگی‌ای که زیسته‌ام، به مردی که بوده‌ام.»"),
            StoryParagraph("'And perhaps that is enough,' he continued. 'Perhaps that is the real crime, the only crime, the crime we all commit: to live badly, to love badly, to waste the gift of life.'", "ادامه داد: «و شاید همین کافی است. شاید این جنایت واقعی است، تنها جنایت، جنایتی که همه‌مان مرتکب می‌شویم: بد زیستن، بد عشق ورزیدن، هدر دادن هدیه زندگی.»"),
            StoryParagraph("And so Dmitri went to Siberia, and Ivan went mad, and Alyosha remained, alone with his grief and his faith.", "و اینگونه دمیتری به سیبری رفت و ایوان دیوانه شد و آلیوشا ماند، تنها با اندوهش و ایمانش.")
        )
    )

    // ─────────── فصل ۵: پسرها و آینده ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "The Boys and the Future", titlePersian = "پسرها و آینده",
        paragraphs = listOf(
            StoryParagraph("Alyosha loved the children of the town, and they loved him.", "آلیوشا بچه‌های شهر را دوست داشت و آن‌ها او را دوست داشتند."),
            StoryParagraph("He taught them, and he played with them, and he listened to their troubles, and he did not judge them, and he did not lecture them.", "به آن‌ها آموزش می‌داد و با آن‌ها بازی می‌کرد و به مشکلاتشان گوش می‌داد و قضاوتشان نمی‌کرد و نصیحتشان نمی‌کرد."),
            StoryParagraph("There was a boy named Kolya Krasotkin, twelve years old, brilliant and proud, who loved Alyosha more than he loved anyone in the world.", "پسری بود به نام کولیا کراسوتکین، دوازده ساله، درخشان و مغرور، که آلیوشا را بیش از هر کسی در جهان دوست داشت."),
            StoryParagraph("Kolya was a leader among the boys, a reader of books, a young man who thought of himself as an adult, though he was only a child.", "کولیا رهبر میان پسرها بود، خواننده کتاب، جوانی که خود را بزرگسال می‌پنداشت هرچند تنها یک بچه بود."),
            StoryParagraph("There was another boy named Ilyusha, nine years old, sick and small, whose father had been humiliated by Dmitri Karamazov.", "پسری دیگر بود به نام ایلیوشا، نه ساله، مریض و کوچک، که پدرش توسط دمیتری کارامازوف تحقیر شده بود."),
            StoryParagraph("Ilyusha had seen his father's humiliation, and it had broken his heart, and he had grown pale and thin and silent.", "ایلیوشا تحقیر پدرش را دیده بود و آن قلبش را شکسته بود و رنگ‌پریده و لاغر و ساکت شده بود."),
            StoryParagraph("The other boys had taunted him, had thrown stones at him, had made his life miserable; but Alyosha had intervened, had told them to stop, had shown them the cruelty of their actions.", "پسرهای دیگر مسخره‌اش می‌کردند، سنگ به سمتش پرت می‌کردند، زندگی‌اش را بدبخت می‌کردند؛ اما آلیوشا دخالت کرده بود، به آن‌ها گفته بود متوقف شوند، ظلم اعمالشان را نشانشان داده بود."),
            StoryParagraph("And slowly, the boys had begun to change, had begun to feel sorry for Ilyusha, had begun to try to make amends.", "و آرام‌آرام، پسرها شروع به تغییر کرده بودند، شروع به دلسوزی برای ایلیوشا کرده بودند، شروع به تلاش برای جبران کرده بودند."),
            StoryParagraph("Kolya, especially, had been transformed by Alyosha's influence; he had learned that strength is not cruelty, that intelligence is not arrogance, that pride is not honor.", "کولیا به‌ویژه توسط تأثیر آلیوشا دگرگون شده بود؛ آموخته بود که قدرت بی‌رحمی نیست، هوش تکبر نیست، غرور ناموس نیست."),
            StoryParagraph("One day, Alyosha told the boys about his brother Dmitri, about the trial, about the punishment.", "یک روز، آلیوشا به پسرها از برادرش دمیتری گفت، از محاکمه، از مجازات."),
            StoryParagraph("'He is innocent,' Alyosha said. 'But he accepted his punishment because he believed he was guilty of something else, something deeper, something we are all guilty of.'", "آلیوشا گفت: «او بی‌گناه است. اما مجازاتش را پذیرفت چون باور داشت به چیز دیگری گناهکار است، چیز عمیق‌تری، چیزی که همه‌مان به آن گناهکاریم.»"),
            StoryParagraph("'What is that?' Kolya asked.", "کولیا پرسید: «آن چیز چیست؟»"),
            StoryParagraph("'To have lived without love,' Alyosha said. 'To have wasted the gift of life. To have hurt others without knowing it, or without caring.'", "آلیوشا گفت: «بدون عشق زیسته باشیم. هدیه زندگی را هدر داده باشیم. دیگران را بدون دانستن، یا بدون اهمیت دادن، آزرده باشیم.»"),
            StoryParagraph("The boys were silent; they did not fully understand, but they felt that something important had been said.", "پسرها ساکت شدند؛ کاملاً نفهمیدند اما حس کردند چیزی مهم گفته شده."),
            StoryParagraph("'I want to be good,' Kolya said, at last. 'I want to be like you, Alyosha. I want to love everyone.'", "کولیا سرانجام گفت: «می‌خواهم خوب باشم. می‌خواهم مثل تو باشم، آلیوشا. می‌خواهم همه را دوست بدارم.»"),
            StoryParagraph("'You can,' Alyosha said. 'You can be better than me. You can love more than me. You can be kinder, braver, wiser. That is what life is for.'", "آلیوشا گفت: «می‌توانی. می‌توانی از من بهتر باشی. می‌توانی بیشتر از من عشق بورزی. می‌توانی مهربان‌تر باشی، شجاع‌تر، فرزانه‌تر. زندگی برای همین است.»"),
            StoryParagraph("And then Ilyusha became very sick, and the boys gathered around his bed, and they waited.", "و بعد ایلیوشا خیلی مریض شد و پسرها دور تختش جمع شدند و منتظر ماندند."),
            StoryParagraph("Kolya visited him every day; he read to him, he talked to him, he held his hand.", "کولیا هر روز به دیدنش می‌رفت؛ برایش می‌خواند، با او صحبت می‌کرد، دستش را می‌گرفت."),
            StoryParagraph("'I am not afraid to die,' Ilyusha said, one day, in a voice that was barely a whisper. 'I am only sad to leave you all.'", "ایلیوشا یک روز با صدایی که تقریباً زمزمه بود گفت: «از مردن نمی‌ترسم. تنها غمگینم که شما را ترک می‌کنم.»"),
            StoryParagraph("'You will not leave us,' Kolya said, and tears were running down his cheeks. 'You will always be with us. In our hearts. In our memories.'", "کولیا گفت: «ترکمان نمی‌کنی.» و اشک بر گونه‌هایش جاری بود. «همیشه با ما خواهی بود. در قلب‌هایمان. در خاطراتمان.»"),
            StoryParagraph("Ilyusha smiled, and closed his eyes, and slept; and when he woke, he was no longer in pain.", "ایلیوشا لبخند زد و چشمانش را بست و خوابید؛ و وقتی بیدار شد، دیگر دردی نداشت."),
            StoryParagraph("His mother held him, and his father wept, and the boys stood around the bed in silence.", "مادرش در آغوشش گرفت و پدرش گریست و پسرها در سکوت دور تخت ایستادند."),
            StoryParagraph("And then, quietly, peacefully, Ilyusha died.", "و بعد، آرام، صلح‌جویانه، ایلیوشا مرد."),
            StoryParagraph("The boys wept, and Alyosha wept with them, and they all held each other, and they did not speak.", "پسرها گریستند و آلیوشا با آن‌ها گریست و همه همدیگر را در آغوش گرفتند و صحبت نکردند."),
            StoryParagraph("At the funeral, Alyosha spoke to the boys, and his words would be remembered by them all their lives.", "در خاکسپاری، آلیوشا با پسرها صحبت کرد و کلماتش تا آخر عمر به یادشان می‌ماند."),
            StoryParagraph("'My dear boys,' he said, 'my dear friends, we shall soon be parted. We shall not see each other for a long time. But there is one thing I want you to remember.'", "گفت: «پسرهای عزیزم، دوستان عزیزم، به‌زودی از هم جدا می‌شویم. مدت‌ها همدیگر را نمی‌بینیم. اما یک چیز می‌خواهم به یاد بیاورید.»"),
            StoryParagraph("'Remember this moment. Remember how you felt when you loved Ilyusha, when you were kind to him, when you tried to make his life happy.'", "«این لحظه را به یاد بیاورید. به یاد بیاورید وقتی ایلیوشا را دوست داشتید چه حسی داشتید، وقتی با او مهربان بودید، وقتی تلاش کردید زندگی‌اش را خوشحال کنید.»"),
            StoryParagraph("'Remember that a good memory is the most precious thing in the world. And if you hold on to a good memory, it can save you, no matter how far you fall, no matter how lost you become.'", "«به یاد بیاورید که خاطره خوب گرانبهاترین چیز جهان است. و اگر خاطره خوبی را نگه دارید، می‌تواند نجاتتان دهد، هر چقدر هم که افتاده باشید، هر چقدر هم که گم شده باشید.»"),
            StoryParagraph("'And if you remember this,' Alyosha said, 'then perhaps one day, when you are old and gray, you will say to your children: we were once good, we were once kind, we were once alive.'", "آلیوشا گفت: «و اگر این را به یاد بیاورید، شاید روزی، وقتی پیر و خاکستری شدید، به فرزندانتان بگویید: زمانی خوب بودیم، زمانی مهربان بودیم، زمانی زنده بودیم.»"),
            StoryParagraph("'And perhaps that will be enough. Perhaps that will be everything.'", "«و شاید همین کافی باشد. شاید همین همه چیز باشد.»"),
            StoryParagraph("The boys wept, and laughed, and embraced each other, and promised to remember.", "پسرها گریستند و خندیدند و همدیگر را در آغوش گرفتند و قول دادند به یاد بیاورند."),
            StoryParagraph("And Alyosha walked away, alone, but not lonely, sad, but not despairing, carrying within him a hope that nothing could destroy.", "و آلیوشا دور شد، تنها اما نه دل‌گیر، غمگین اما نه ناامید، در درونش امیدی حمل می‌کرد که هیچ چیز نمی‌توانست نابودش کند."),
            StoryParagraph("For he had learned, at last, the truth that Dostoevsky wanted to teach: that love is stronger than death, that hope is stronger than despair, that a good memory is stronger than all the evil in the world.", "زیرا سرانجام آموخته بود حقیقتی که داستایفسکی می‌خواست بیاموزد: که عشق از مرگ قوی‌تر است، امید از ناامیدی قوی‌تر، خاطره خوب از تمام شر جهان قوی‌تر.")
        )
    )

    // ─────────── فصل ۶: معنا ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("The Brothers Karamazov, published in 1880, is the last and greatest novel of Fyodor Dostoevsky, and many critics consider it the greatest novel ever written.", "برادران کارامازوف، منتشرشده در ۱۸۸۰، آخرین و بزرگ‌ترین رمان فیودور داستایفسکی است و بسیاری از منتقدان آن را بزرگ‌ترین رمان نوشته‌شده می‌دانند."),
            StoryParagraph("It is a murder mystery, a family drama, a philosophical treatise, a spiritual meditation, and a religious vision — all woven together into a single, overwhelming whole.", "معمای قتل است، درام خانوادگی، رساله فلسفی، مراقبه روحانی و بینش دینی — همه در هم بافته شده در کلیتی یگانه و طاقت‌فرسا."),
            StoryParagraph("At its heart are three brothers — Dmitri, Ivan, and Alyosha — who represent three different responses to the problem of human existence.", "در قلبش سه برادرند — دمیتری، ایوان و آلیوشا — که سه پاسخ متفاوت به مشکل وجود انسانی را مجسم می‌کنند."),
            StoryParagraph("Dmitri is the man of passion, the man who lives through his senses, the man who is driven by desire and who suffers because of it.", "دمیتری مرد شور است، مردی که از طریق حواسش زندگی می‌کند، مردی که توسط میل رانده می‌شود و به همین دلیل رنج می‌کشد."),
            StoryParagraph("Ivan is the man of intellect, the man who lives through his mind, the man who questions everything and who cannot accept any answer.", "ایوان مرد عقل است، مردی که از طریق ذهنش زندگی می‌کند، مردی که همه چیز را زیر سؤال می‌برد و هیچ پاسخی را نمی‌پذیرد."),
            StoryParagraph("Alyosha is the man of faith, the man who lives through his heart, the man who loves without understanding and who trusts without proof.", "آلیوشا مرد ایمان است، مردی که از طریق قلبش زندگی می‌کند، مردی که بدون فهمیدن عشق می‌ورزد و بدون اثبات اعتماد می‌کند."),
            StoryParagraph("Each of them, in his own way, is seeking the same thing: meaning, purpose, a reason to live.", "هر یک از آنان، به شیوه خودش، در جستجوی همان چیز است: معنا، هدف، دلیلی برای زندگی."),
            StoryParagraph("And each of them, in his own way, finds it — or fails to find it — depending on the path he has chosen.", "و هر یک از آنان، به شیوه خودش، پیدایش می‌کند — یا نمی‌یابد — بسته به راهی که برگزیده."),
            StoryParagraph("Dmitri's passion leads him to suffering, but suffering purifies him, and through suffering he finds redemption.", "شور دمیتری او را به رنج می‌کشاند، اما رنج پاکش می‌کند و از طریق رنج رستگاری می‌یابد."),
            StoryParagraph("Ivan's intellect leads him to despair, and despair destroys him, and he ends the novel in madness.", "عقل ایوان او را به ناامیدی می‌کشاند و ناامیدی نابودش می‌کند و رمان را در جنون پایان می‌دهد."),
            StoryParagraph("Alyosha's faith leads him to love, and love saves him, and he ends the novel with hope.", "ایمان آلیوشا او را به عشق می‌کشاند و عشق نجاتش می‌دهد و رمان را با امید پایان می‌دهد."),
            StoryParagraph("But Dostoevsky is not making a simple moral judgment; he is showing us the consequences of different ways of being, and asking us to choose.", "اما داستایفسکی قضاوت اخلاقی ساده‌ای نمی‌کند؛ پیامدهای شیوه‌های مختلف بودن را نشانمان می‌دهد و از ما می‌خواهد بگزینیم."),
            StoryParagraph("The novel's most famous section, The Grand Inquisitor, is a philosophical argument against God, and it is one of the most powerful arguments ever written.", "مشهورترین بخش رمان، بازپرس بزرگ، استدلالی فلسفی علیه خداست و یکی از قوی‌ترین استدلال‌هایی است که تا کنون نوشته شده."),
            StoryParagraph("Yet the novel itself is not an argument against God; it is an argument for love, for faith, for hope, in the face of all the reasons not to believe.", "با این حال خود رمان استدلالی علیه خدا نیست؛ استدلالی برای عشق، برای ایمان، برای امید است، در برابر تمام دلایلی که نباید باور کرد."),
            StoryParagraph("Dostoevsky had suffered deeply in his own life: he had been sentenced to death, reprieved at the last moment, sent to Siberia for four years, suffered from epilepsy, lost his children.", "داستایفسکی در زندگی خودش عمیقاً رنج کشیده بود: به مرگ محکوم شده بود، در آخرین لحظه بخشیده شده بود، چهار سال به سیبری فرستاده شده بود، از صرع رنج می‌برد، فرزندانش را از دست داده بود."),
            StoryParagraph("And yet, out of all that suffering, he wrote a novel that is, in its deepest essence, a hymn to life, a celebration of love, a testament to hope.", "و با این حال، از تمام آن رنج، رمانی نوشت که در عمیق‌ترین جوهرش، سرودی برای زندگی است، جشنی برای عشق، شاهدی برای امید."),
            StoryParagraph("The novel is not optimistic in a naive sense; it does not pretend that everything is fine, that suffering does not exist, that evil is not real.", "رمان به معنای ساده‌لوحانه‌ای خوش‌بینانه نیست؛ تظاهر نمی‌کند همه چیز خوب است، که رنج وجود ندارد، که شر واقعی نیست."),
            StoryParagraph("It shows us murder and madness, cruelty and betrayal, lust and greed, all the darkness that is in the human heart.", "قتل و جنون را نشانمان می‌دهد، بی‌رحمی و خیانت، شهوت و طمع، تمام تاریکی که در قلب انسانی است."),
            StoryParagraph("But it also shows us love and kindness, faith and hope, redemption and resurrection, all the light that is in the human heart.", "اما عشق و مهربانی را هم نشانمان می‌دهد، ایمان و امید، رستگاری و رستاخیز، تمام نوری که در قلب انسانی است."),
            StoryParagraph("And it shows us that the light is stronger than the darkness, that love is stronger than hate, that life is stronger than death.", "و نشانمان می‌دهد که نور از تاریکی قوی‌تر است، عشق از نفرت قوی‌تر، زندگی از مرگ قوی‌تر."),
            StoryParagraph("This is the message of Alyosha, the message that Dostoevsky wanted to leave with his readers, the message that echoes through the centuries.", "این پیام آلیوشا است، پیامی که داستایفسکی می‌خواست با خوانندگانش بگذارد، پیامی که در طول قرن‌ها پژواک می‌کند."),
            StoryParagraph("'Love everything,' Father Zosima says. 'Love the animals, love the plants, love every thing. If you love everything, you will perceive the divine mystery in things.'", "پدر زوسیما می‌گوید: «همه چیز را دوست بدارید. حیوانات را دوست بدارید، گیاهان را، هر چیزی را. اگر همه چیز را دوست بدارید، رمز الهی را در چیزها درک خواهید کرد.»"),
            StoryParagraph("'And you will come at last to love the whole world with an all-embracing love,' the elder continues. 'And then you will understand the truth, and you will be free.'", "پیر ادامه می‌دهد: «و سرانجام خواهید رسید به عشق ورزیدن به تمام جهان با عشقی فراگیر. و آن وقت حقیقت را خواهید فهمید و آزاد خواهید بود.»"),
            StoryParagraph("This is not a philosophy of comfort, not a religion of easy answers, not a faith that avoids the hard questions.", "این فلسفه راحتی نیست، دین پاسخ‌های آسان نیست، ایمانی که از پرسش‌های دشوار بگریزد نیست."),
            StoryParagraph("It is a philosophy that looks into the abyss and still chooses hope; a religion that faces suffering and still chooses love; a faith that doubts everything and still chooses to believe.", "فلسفه‌ای است که به پرتگاه می‌نگرد و هنوز امید را برمی‌گزیند؛ دینی است که با رنج روبرو می‌شود و هنوز عشق را برمی‌گزیند؛ ایمانی است که به همه چیز شک می‌کند و هنوز باور کردن را برمی‌گزیند."),
            StoryParagraph("And that, perhaps, is the deepest wisdom: not that faith is easy, but that it is possible; not that love is simple, but that it is real; not that hope is certain, but that it is worth having.", "و این، شاید، عمیق‌ترین خرد است: نه اینکه ایمان آسان است، بلکه ممکن است؛ نه اینکه عشق ساده است، بلکه واقعی است؛ نه اینکه امید یقینی است، بلکه ارزش داشتن دارد."),
            StoryParagraph("The Brothers Karamazov is not a novel to be read once and forgotten; it is a novel to be lived, to be struggled with, to be returned to again and again throughout a lifetime.", "برادران کارامازوف رمانی نیست که یک بار خوانده و فراموش شود؛ رمانی است که زیسته شود، با آن دست‌وپنجه نرم شود، در طول یک عمر دوباره و دوباره به آن بازگردیم."),
            StoryParagraph("For its questions are our questions; its struggles are our struggles; its hopes are our hopes.", "زیرا پرسش‌هایش پرسش‌های ماست؛ کشمکش‌هایش کشمکش‌های ما؛ امیدهایش امیدهای ما."),
            StoryParagraph("We are all Karamazovs, in one way or another; we are all caught between passion and reason, between doubt and faith, between despair and hope.", "همه‌مان به نوعی کارامازوفیم؛ همه‌مان میان شور و عقل، میان شک و ایمان، میان ناامیدی و امید گرفتاریم."),
            StoryParagraph("And we all, like the brothers, must find our own way, must make our own choice, must live our own life.", "و همه‌مان، همچون برادران، باید راه خودمان را بیابیم، انتخاب خودمان را بکنیم، زندگی خودمان را بکنیم."),
            StoryParagraph("And the only guidance the novel gives us is this: love. Love everything. Love everyone. And trust that love will save us.", "و تنها راهنمایی‌ای که رمان به ما می‌دهد این است: عشق. همه چیز را دوست بدارید. همه را دوست بدارید. و اعتماد کنید که عشق نجاتتان می‌دهد."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز."),
            StoryParagraph("For the story of the Karamazov brothers is not finished; it is being written every day, in every life, in every heart.", "زیرا داستان برادران کارامازوف تمام نشده؛ هر روز نوشته می‌شود، در هر زندگی، در هر قلب."),
            StoryParagraph("And it will be finished, at last, when love has become the only law, when every tear has been wiped away, when the world has become what it was always meant to be.", "و سرانجام تمام می‌شود، وقتی عشق تنها قانون شده، وقتی هر اشکی پاک شده، وقتی جهان به آنچه همیشه باید می‌بود تبدیل شده.")
        )
    )
}